head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String((dma_pageContext.get("keyword") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.list();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 키 form 를 쓰는 tx 가 3개다(tx_fn_Excel, tx_fn_AllPrint, tx_fn_XfmUpdate)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_2_onsubmit
 * @description form_2 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_2_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50000.form_2_onsubmit' }); }
};

/**
 * @method
 * @name ipt_keyword_onkeyup
 * @description ipt_keyword 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_keyword_onkeyup = async function(e){
    try {
        await scwin.onEnter()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50000.ipt_keyword_onkeyup' }); }
};

/**
 * @method
 * @name img_98_onclick
 * @description img_98 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_98_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50000.img_98_onclick' }); }
};

/**
 * @method
 * @name img_113_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_113_onclick = async function(e){
    try {
        await scwin.excel()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50000.img_113_onclick' }); }
};

/**
 * @method
 * @name img_114_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_114_onclick = async function(e){
    try {
        await scwin.allPrint()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50000.img_114_onclick' }); }
