/**
 * @method
 * @name img_115_onclick
 * @description img_115 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_115_onclick = async function(e){
    try {
        await scwin.xfmUpdate()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50000.img_115_onclick' }); }
};

/**
 * @method
 * @name img_117_onclick
 * @description img_117 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_117_onclick = function(e){
    try {
        scwin.goInsert()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50000.img_117_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Content
 * @description Content 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Content = async function () {
    const sbmOptions = {
        id: "tx_fn_Content",
        method: "post",
        action: "/filing/findForm.do",
        ref: "dma_ContentReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Excel
 * @description Excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Excel = async function () {
    const sbmOptions = {
        id: "tx_fn_Excel",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_ExcelReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_AllPrint
 * @description All Print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_AllPrint = async function () {
    const sbmOptions = {
        id: "tx_fn_AllPrint",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_AllPrintReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_XfmUpdate
 * @description Xfm Update 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_XfmUpdate = async function () {
    const sbmOptions = {
        id: "tx_fn_XfmUpdate",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_XfmUpdateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_list_xhr
 * @description list xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_list_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_list_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_list_xhr", unresolved: "action:self_submit:tx_list_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent("dma_ContentReq").set("method", "findFormList");
    await scwin.tx_list_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    ($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setValue) ? $c.util.getComponent('formListDiv').setValue(responseText) : (($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setText) ? $c.util.getComponent('formListDiv').setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'formListDiv'), void (responseText)));
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} orderBy orderBy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (orderBy) {
    if (orderBy != null) {
        const prevOrderBy = $c.util.getComponent('dma_ContentReq').get('orderBy');
        $c.util.getComponent('dma_ContentReq').set('orderBy', orderBy);
        if (prevOrderBy === orderBy) {
            const ascDiv = $c.util.getComponent('dma_ContentReq').get('ascDiv');
            if (ascDiv === "asc") {
                $c.util.getComponent('dma_ContentReq').set('ascDiv', "desc");
            } else {
                $c.util.getComponent('dma_ContentReq').set('ascDiv', "asc");
            }
        } else {
            $c.util.getComponent('dma_ContentReq').set('ascDiv', "asc");
        }
    } else {
        $c.util.getComponent('dma_ContentReq').set('ascDiv', "asc");
    }
    $c.util.getComponent('dma_ContentReq').set('pageIndex', 1);
    await scwin.list();
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onEnter = async function () {
    if (event.keyCode === 13) {
        await scwin.search();
    }
};

/**
 * @method
 * @name content
 * @description content 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.content = async function (formCd, formVer) {
    $c.util.getComponent('dma_ContentReq').set('formCd', formCd);
    $c.util.getComponent('dma_ContentReq').set('formVer', formVer);
    $c.util.getComponent("dma_ContentReq").set("method", "findForm");
    scwin.form_listForm.action = "/filing/findForm.do";
    await scwin.tx_fn_Content();
};

/**
 * @method
 * @name popFssTransform
 * @description pop Fss Transform 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popFssTransform = async function () {
    const _url = "/filing/fssForm.do?method=prepareTransformFssForm";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "fssFormPop", popupName: "fssFormPop" }, {});
};

/**
 * @method
 * @name goInsert
 * @description go Insert 처리
 * @returns {void}
 * @hidden N
 */
scwin.goInsert = function () {
    $c.win.moveUrl("/filing/updateForm.do?method=prepareUpdateFormInfo&mode=create");
};

/**
 * @method
 * @name findVersioningForms
 * @description find Versioning Forms 처리
 * @param {String} formCd formCd
 * @returns {void}
 * @hidden N
 */
scwin.findVersioningForms = function (formCd) {
    const _url = "/filing/findForm.do?method=findVersioningForms&formCd=" + formCd;
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=300";
    const winTitle = "버전별 목록";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "formVerPop", type: "pageFramePopup", title: winTitle, width: "700px", height: "300px" }, {});
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function () {
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent("dma_ContentReq").set("method", "downloadFormList");
    scwin.form_listForm.target = "hiddenFrame";
    await scwin.tx_fn_Excel();
};

/**
 * @method
 * @name allPrint
 * @description all Print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.allPrint = async function () {
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent("dma_ContentReq").set("method", "findPrintTargetList");
    scwin.form_listForm.target = "";
    await scwin.tx_fn_AllPrint();
};

/**
 * @method
 * @name xfmUpdate
 * @description xfm Update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.xfmUpdate = async function () {
    const _confirm = await $c.win.confirm("서식양식일괄업데이트를 하시겠습니까?");
    if (!_confirm) {
        return;
    }
    const _url = "/filing/form/multiFile_Load.jsp";
    const _props = "toolbar=no,menubar=no,scrollbars=no,status=yes,resizable=no,width=450,height=300";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "multiFile_Load", popupName: "multiFile_Load", width: "450", height: "300" }, {});
};
